    { term: "COPWE", def: "The Commission for Organizing the Party of the Workers of Ethiopia, set up in December 1979 with Mengistu as chairman." },
    { term: "WPE", def: "The Workers' Party of Ethiopia, proclaimed on 12 September 1984 with Mengistu Haile Mariam as its first Secretary-General." },
    { term: "PDRE", def: "The People's Democratic Republic of Ethiopia, proclaimed by the National Shengo on 11 September 1987, with Mengistu as first civilian president." },
    { term: "Villagization", def: "The program begun in January 1985 to move more than 30 million peasants into larger villages, criticized as an instrument of control which further impoverished the peasantry." }
